# Full solution in one cell - rebuild and solve
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from itertools import combinations

W = 5   # weeks
P = 40  # players
G = 10  # groups
S = 4   # group size

def var(w, p, g):
    return w * P * G + p * G + g + 1

total_vars = W * P * G  # = 2000

solver = Glucose3()

# Constraint 1: Each golfer is in exactly one group per week
for w in range(W):
    for p in range(P):
        solver.add_clause([var(w, p, g) for g in range(G)])
        for g1 in range(G):
            for g2 in range(g1+1, G):
                solver.add_clause([-var(w, p, g1), -var(w, p, g2)])

# Constraint 2: Each group has exactly S=4 players per week
for w in range(W):
    for g in range(G):
        lits = [var(w, p, g) for p in range(P)]
        atmost = CardEnc.atmost(lits, bound=S, encoding=EncType.seqcounter, top_id=total_vars)
        for clause in atmost.clauses:
            solver.add_clause(clause)
            total_vars = max(total_vars, max(abs(l) for l in clause))
        atleast = CardEnc.atleast(lits, bound=S, encoding=EncType.seqcounter, top_id=total_vars)
        for clause in atleast.clauses:
            solver.add_clause(clause)
            total_vars = max(total_vars, max(abs(l) for l in clause))

# Constraint 3: No pair in same group more than once
for p1, p2 in combinations(range(P), 2):
    for w1, w2 in combinations(range(W), 2):
        for g1 in range(G):
            for g2 in range(G):
                solver.add_clause([-var(w1,p1,g1), -var(w1,p2,g1), -var(w2,p1,g2), -var(w2,p2,g2)])

# Symmetry breaking: fix week 0
for p in range(P):
    g = p // 4
    solver.add_clause([var(0, p, g)])

result = solver.solve()
print(f"Result: {'SAT' if result else 'UNSAT'}")

if result:
    model = solver.get_model()
    model_set = set(model)

    schedule = [None] * (W * P)
    for w in range(W):
        for p in range(P):
            for g in range(G):
                if var(w, p, g) in model_set:
                    schedule[w * P + p] = g
                    break

    # Verify
    violations = 0
    pair_weeks = {}
    for w in range(W):
        groups = {}
        for p in range(P):
            g = schedule[w*P+p]
            if g not in groups:
                groups[g] = []
            groups[g].append(p)
        for g, members in groups.items():
            assert len(members) == S, f"Week {w}, group {g} has {len(members)} members"
            for p1, p2 in combinations(members, 2):
                key = (min(p1,p2), max(p1,p2))
                if key in pair_weeks:
                    violations += 1
                else:
                    pair_weeks[key] = w

    print(f"Violations: {violations}")
    print(f"Schedule length: {len(schedule)}")

    # Print schedule nicely
    for w in range(W):
        groups = {}
        for p in range(P):
            g = schedule[w*P+p]
            if g not in groups:
                groups[g] = []
            groups[g].append(p)
        print(f"Week {w}: {dict(sorted(groups.items()))}")

    print("\nFlat schedule:")
    print(schedule)
